"use strict";(globalThis.webpackChunkgrc||=[]).push([[40331],{39856(e){e.exports=JSON.parse('{"name":"Dr. Luke Logan","title":"Assistant Research Professor","bio":"Dr. Luke Logan is an Assistant Research Professor at the Gnosis Research Center. He completed his PhD at Illinois Institute of Technology (defended 2025, degree conferred December 2025). His research focuses on making distributed storage and operating systems more programmable, portable, and performant. He is the developer of LabStor (SC\'22), MegaMmap (SC\'24), and pMEMCPY, with contributions to DAOS evaluation and heterogeneous storage optimization. Luke first joined IIT as an undergraduate researcher in 2017 before beginning his PhD in 2020.","cardBio":"Developer of LabStor, MegaMmap, and pMEMCPY. Programmable distributed storage and heterogeneous memory systems.","image":"logan.webp","links":{"email":"llogan@illinoistech.edu","website":"https://lukemartinlogan.github.io/professional-website/","scholar":"https://scholar.google.com/citations?user=Ljn7CmYAAAAJ","linkedin":"https://www.linkedin.com/in/luke-logan","github":"https://github.com/lukemartinlogan","orcid":"https://orcid.org/0000-0002-7487-1947"},"researchInterests":["Heterogeneous Storage","I/O Optimization","Persistent Memory","Distributed Systems"],"order":4,"slug":"luke-logan","type":"faculty","joinedDate":"2017-08-01","graduatedDate":"2025-12-15","alumniStatus":{"graduated":true,"year":2025,"currentPosition":"Assistant Research Professor","currentOrg":"Gnosis Research Center, Illinois Institute of Technology"}}')}}]);